import{_ as s,c as a,o as i,a4 as t}from"./chunks/framework.iMXuyU9c.js";const g=JSON.parse('{"title":"远程控制台上传下载文件","description":"","frontmatter":{},"headers":[],"relativePath":"Linux_About/远程控制台上传下载文件.md","filePath":"Linux_About/远程控制台上传下载文件.md"}'),e={name:"Linux_About/远程控制台上传下载文件.md"},p=t(`<h1 id="远程控制台上传下载文件" tabindex="-1">远程控制台上传下载文件 <a class="header-anchor" href="#远程控制台上传下载文件" aria-label="Permalink to &quot;远程控制台上传下载文件&quot;">​</a></h1><pre><code>该文创建于 2024/12/09
文章参考 []()
</code></pre><p>写在前面:下列方式我都不会用,xshell和xftp软件好用</p><h2 id="rz-sz命令实现-ssh下" tabindex="-1">rz sz命令实现 (SSH下) <a class="header-anchor" href="#rz-sz命令实现-ssh下" aria-label="Permalink to &quot;rz sz命令实现 (SSH下)&quot;">​</a></h2><p><a href="https://cnblogs.com/Formulate0303/p/17385451.html" target="_blank" rel="noreferrer">返回主页马踏飞燕Beautiful.博客园</a> 这两个命令可以直接上传、下载文件，并自动弹出文件选择框，操作非常方便和习惯。但是要使用的话，需要远程Linux服务器安装了这两个命令，也就是安装了lszrz包。</p><h3 id="rz命令" tabindex="-1">rz命令 <a class="header-anchor" href="#rz命令" aria-label="Permalink to &quot;rz命令&quot;">​</a></h3><p>rz 命令(Receive ZMODEM)，使用 ZMODEM 协议，将本地文件批量上传到远程 Linux/Unix 服务器，注意不能上传文件夹。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd [目标路径]</span></span>
<span class="line"><span>rz</span></span></code></pre></div><p>输入 rz 回车后，会出现文件选择对话框，选择需要上传文件，一次可以指定多个文件，上传到服务器的路径为当前执行 rz 命令的目录。 <img src="https://img2023.cnblogs.com/blog/1130145/202305/1130145-20230509161242982-1227444631.png" alt="图片" loading="lazy"></p><h3 id="sz命令" tabindex="-1">sz命令 <a class="header-anchor" href="#sz命令" aria-label="Permalink to &quot;sz命令&quot;">​</a></h3><p>sz命令是利用ZModem协议来从Linux服务器传送文件到本地，一次可以传送一个或多个文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sz [目标路径/目标文件.后缀]</span></span></code></pre></div><p><img src="https://img2023.cnblogs.com/blog/1130145/202305/1130145-20230509161304069-99174534.png" alt="图片" loading="lazy"></p><h2 id="ftp" tabindex="-1">ftp <a class="header-anchor" href="#ftp" aria-label="Permalink to &quot;ftp&quot;">​</a></h2><p>Windows客户端使用方式: 打开文件资源管理器(window+e),在地址栏里写入&#39;<a href="ftp://ip/" target="_blank" rel="noreferrer">ftp://ip/</a>&#39;</p><h2 id="pscp和scp-ssh下" tabindex="-1">pscp和scp (SSH下) <a class="header-anchor" href="#pscp和scp-ssh下" aria-label="Permalink to &quot;pscp和scp (SSH下)&quot;">​</a></h2><h3 id="pscp" tabindex="-1">pscp <a class="header-anchor" href="#pscp" aria-label="Permalink to &quot;pscp&quot;">​</a></h3><p>需要安装PuTTY PuTTY的pscp命令,是基于SSH的命令行工具,用于在Windows和Linux之间安全的传输文件。 下载</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pscp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> username@linux_host://path/to/remote/file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ath</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ocal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">irectory</span></span></code></pre></div><p>其中,username是Linux系统的用户名,linux_host是Linux系统的IP地址或主机名,/path/to/remote/file是Linux系统上的文件路径,C:\\path\\to\\local\\directory是Windows系统上的目标目录。</p><h3 id="scp" tabindex="-1">scp <a class="header-anchor" href="#scp" aria-label="Permalink to &quot;scp&quot;">​</a></h3><p>如果使用标准的scp命令而不是pscp,需要在Windows上安装OpenSSH客户端。 下载</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> username@linux_host://path/to/remote/file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ath</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ocal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">irectory</span></span></code></pre></div>`,23),n=[p];function h(l,r,o,c,d,k){return i(),a("div",null,n)}const F=s(e,[["render",h]]);export{g as __pageData,F as default};
